WITH metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY country, device ORDER BY started_at, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at, id) AS row_seq, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id) AS event_seq_2, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id) AS event_seq_3 FROM sessions) SELECT id, device, started_at, row_seq, event_seq_3 FROM metrics
